var EH = window.__EH || (window.__EH = {});
EH.fmt = function(n){
  n = Math.round(n);
  var s = String(n), out = '', c = 0;
  for(var i = s.length - 1; i >= 0; i--){
    out = s.charAt(i) + out; c++;
    if(c % 3 === 0 && i > 0) out = ',' + out;
  }
  return out;
};
EH.ramp = function(sel, from, to, ms, suffix){
  var el = MSD.q(sel); if(!el) return;
  var steps = Math.max(1, Math.round(ms / 50)), i = 0;
  var id = MSD.every(50, function(){
    i++;
    var p = Math.min(1, i / steps);
    el.textContent = EH.fmt(from + (to - from) * p) + (suffix || '');
    if(p >= 1) clearInterval(id);
  });
};
// Seeded so the city looks identical on every loop and every re-record.
EH.seed = 20260809;
EH.rnd = function(){
  EH.seed = (EH.seed * 1103515245 + 12345) % 2147483648;
  return EH.seed / 2147483648;
};

MSD.cls('.eh-sc', 'on', false);
MSD.cls('#eh-sc-city', 'on', true);
MSD.q('#eh-app').textContent = 'MSDevRide · live ops';
MSD.cls('#eh-health', 'warn', false);
MSD.cls('#eh-health', 'bad', false);
MSD.q('#eh-health-t').textContent = 'streaming';
MSD.cls('.eh-math-r', 'show', false);
MSD.cls('#eh-qbox', 'on', false);
MSD.cls('.eh-team', 'win', false);
MSD.cls('.eh-team', 'lose', false);
MSD.cls('#eh-strip', 'bad', false);
MSD.cls('#eh-strip', 'good', false);
MSD.q('#eh-strip-l').textContent = 'LIVE';
MSD.q('#eh-strip-t').textContent = 'Every driver reports where they are. Nobody asked for a reply.';

var map = MSD.q('#eh-map');
map.innerHTML = '<span class="eh-map-tag" id="eh-map-tag">📍 60,000 drivers online</span>';
for(var i = 0; i < 30; i++){
  var d = document.createElement('span');
  d.className = 'eh-drv';
  d.style.left = (6 + EH.rnd() * 88).toFixed(1) + '%';
  d.style.top = (8 + EH.rnd() * 80).toFixed(1) + '%';
  d.style.setProperty('--phase', (EH.rnd() * 2.2).toFixed(2) + 's');
  map.appendChild(d);
}

EH.ramp('#eh-rate-n', 0, 15000, 2000);

// A ping leaving a driver: a tiny event chip with a real coordinate.
function ping(){
  var el = document.createElement('span');
  el.className = 'eh-ev';
  var lat = (12.90 + EH.rnd() * 0.12).toFixed(4);
  var lng = (77.55 + EH.rnd() * 0.12).toFixed(4);
  el.textContent = 'drv-' + (1000 + Math.floor(EH.rnd() * 8999)) + ' · ' + lat + ',' + lng;
  el.style.left = (4 + EH.rnd() * 62).toFixed(1) + '%';
  el.style.top = (14 + EH.rnd() * 70).toFixed(1) + '%';
  map.appendChild(el);
  MSD.after(1600, function(){ if(el.parentNode) el.parentNode.removeChild(el); });
}
MSD.after(500, function(){
  ping();
  MSD.every(190, ping);
});

